formula.expression:
if(prop("Events").length() > 0,
  prop("Events").first().prop("Status"),
  ""
)

lets(
  activeFiniteWallet, prop("Wallet Type") == "EPA Late 26" or prop("Wallet Type") == "Proklamasi 26" or prop("Wallet Type") == "1945 26" or prop("Wallet Type") == "Garuda 26",
  isWalletParent, activeFiniteWallet and prop("Sale Role") == "Wallet" and not empty(prop("Wallet Value (IDR)")),
  if(not isWalletParent, empty(), prop("Wallet Opening Credit (IDR)") - prop("Wallet Credit Used (IDR)"))
)

lets(
  bs, prop("Balance Sheet"),
  hasAccess, bs.length() > 0,
  if(not hasAccess, 0,
    if(empty(prop("Shared Net Sales (IDR)")), 0,
      prop("Shared Net Sales (IDR)")
      - if(empty(prop("Club Net Sales (IDR)")), 0, prop("Club Net Sales (IDR)"))
      - if(empty(prop("Third Party Net Sales (IDR)")), 0, prop("Third Party Net Sales (IDR)"))
    )
  )
)

if(empty(prop("Scheduled")), "",
  lets(
    /* Get week number and year from scheduled date */
    weekNum, week(prop("Scheduled")),
    yearNum, year(prop("Scheduled")),
    /* Pad week number with leading zero if needed */
    paddedWeek, if(weekNum < 10, "0" + format(weekNum), format(weekNum)),
    /* Format as 'Week XX, YYYY' */
    "Week " + paddedWeek + ", " + format(yearNum)
  )
)

if(empty(prop("Scheduled")),
  empty(),
  /* Format date as full month name and year */
  formatDate(prop("Scheduled"), "MMMM YYYY")
)

if(empty(prop("Scheduled")),
  "",
  /* Calculate quarter from month and format with year */
  "Q" + format(ceil(prop("Scheduled").month() / 3)) + ", " + format(prop("Scheduled").year())
)

if(empty(prop("Scheduled")), empty(),
  "⑥ Tacit Discount (IDR): " + 
  if(empty(prop("Tacit Discount (IDR)")),
    "0",
    format(round(prop("Tacit Discount (IDR)"), 0))
  )
)

if(empty(prop("Scheduled")),
  empty(),
  style("① Total Income (IDR): " + format(round(prop("Total Income (IDR)"), 0)), "b")
)

lets(
  /* Combine all people from access properties and get their display names */
  allAccessNames, concat(prop("Can Edit"), prop("Can Comment"), prop("Can View"))
    .map(current.name()),
  /* Check for group membership in priority order */
  ifs(
    allAccessNames.includes("Team"), "Team",
    allAccessNames.includes("Leadership"), "Leadership",
    allAccessNames.includes("Owners"), "Owners",
    "Admin"
  )
)

lets(
  walletValue, prop("Wallet Value (IDR)"),
  isWalletParent, not empty(walletValue),
  if(prop("Sale Status") == "Cancelled",
    0,
    if(isWalletParent,
      walletValue,
      lets(
        studentCount, prop("Students").length(),
        saleType, prop("Sale Type"),
        if(studentCount == 0 or empty(prop("Effective Coaching Rate (IDR)")),
          0,
          if(saleType == "Private Lesson" or saleType == "Clinic",
            round(studentCount * prop("Effective Coaching Rate (IDR)") * prop("Financial Pricing Hours")),
            round(studentCount * prop("Effective Coaching Rate (IDR)"))
          )
        )
      )
    )
  )
)

lets(
  parentWalletRows, prop("Group").filter(not empty(current.prop("Wallet Value (IDR)")) and current.prop("Sale Role") == "Wallet" and current.prop("Sale Status") != "Cancelled"),
  parentWalletType, if(parentWalletRows.length() == 1, parentWalletRows.map(current.prop("Wallet Type")).first(), ""),
  activeFiniteWallet, parentWalletType == "EPA Late 26" or parentWalletType == "Proklamasi 26" or parentWalletType == "1945 26" or parentWalletType == "Garuda 26",
  eligibleChild, empty(prop("Wallet Value (IDR)")) and parentWalletRows.length() == 1 and activeFiniteWallet and prop("Sale Type") == "Private Lesson" and prop("Discount Reason").includes("Wallet: Paid"),
  if(not eligibleChild or prop("Sale Status") == "Cancelled", empty(),
    round(if(empty(prop("Tacit Discount (IDR)")), 0, prop("Tacit Discount (IDR)")), 0)
  )
)

lets(
  bs, prop("Balance Sheet"),
  hasAccess, bs.length() > 0,
  if(not hasAccess, 0,
    lets(
      clubPct, if(empty(prop("Club %")), 0, prop("Club %")),
      protectedAcademyFees, prop("Tacit List Price (IDR)") * (1 - if(empty(prop("Shared Discount %")), 0, prop("Shared Discount %"))),
      protectedNetSales, protectedAcademyFees * (1 - if(empty(prop("VAT %")), 0, prop("VAT %")) - if(empty(prop("Platform Commission %")), 0, prop("Platform Commission %")) - if(empty(prop("Transaction Fee %")), 0, prop("Transaction Fee %"))),
      if(prop("Sale Role") == "Cost", 0, round(protectedNetSales * clubPct, 0))
    )
  )
)

lets(
  bs, prop("Balance Sheet"),
  hasAccess, bs.length() > 0,
  if(not hasAccess, 0,
    lets(
      thirdPartyPct, if(empty(prop("Third Party %")), 0, prop("Third Party %")),
      protectedAcademyFees, prop("Tacit List Price (IDR)") * (1 - if(empty(prop("Shared Discount %")), 0, prop("Shared Discount %"))),
      protectedNetSales, protectedAcademyFees * (1 - if(empty(prop("VAT %")), 0, prop("VAT %")) - if(empty(prop("Platform Commission %")), 0, prop("Platform Commission %")) - if(empty(prop("Transaction Fee %")), 0, prop("Transaction Fee %"))),
      if(prop("Sale Role") == "Cost", 0, round(protectedNetSales * thirdPartyPct, 0))
    )
  )
)

ifs(
  prop("Sale Role") == "Cost",
  lets(
    courtRental, if(empty(prop("Court Rental (IDR)")), 0, prop("Court Rental (IDR)")),
    collected, prop("Item").map(current.prop("Court Contribution (IDR)")).sum(),
    max(courtRental - collected, 0)
  ),
  prop("Sale Role") == "Revenue",
  if(prop("Sale Type") == "Clinic",
    if(empty(prop("Effective Coaching Rate (IDR)")) or empty(prop("Clinic (IDR PP)")), 0,
      round((prop("Clinic (IDR PP)") - prop("Effective Coaching Rate (IDR)")) * prop("Financial Pricing Hours"), 0)
    ),
    lets(
      parentRow, prop("Group").first(),
      if(empty(parentRow), 0,
        lets(
          parentCourtRental, if(empty(parentRow.prop("Court Rental (IDR)")), 0, parentRow.prop("Court Rental (IDR)")),
          parentCapacity, if(empty(parentRow.prop("Event Capacity")), 0, parentRow.prop("Event Capacity").first()),
          if(parentCapacity == 0, 0, parentCourtRental / parentCapacity)
        )
      )
    )
  ),
  0
)

if(
  prop("Financial Route") == "Payment V1",
  if(empty(prop("Resolved Coaching Rate (IDR)")), empty(), prop("Resolved Coaching Rate (IDR)")),
  prop("Price Per Student (IDR)")
)

if(empty(prop("Academy Fees (IDR)")), 0,
  prop("Academy Fees (IDR)") -
  if(empty(prop("VAT (IDR)")), 0, prop("VAT (IDR)")) -
  prop("Academy Fees (IDR)") * if(empty(prop("Platform Commission %")), 0, prop("Platform Commission %")) -
  prop("Academy Fees (IDR)") * if(empty(prop("Transaction Fee %")), 0, prop("Transaction Fee %"))
)

lets(
  /* Get base values with defaults */
  listPrice, if(empty(prop("Tacit List Price (IDR)")), 0, prop("Tacit List Price (IDR)")),
  offPeakDiscount, if(empty(prop("Shared Discount %")), 0, prop("Shared Discount %")),
  discretionaryDiscount, if(empty(prop("Tacit Discount %")), 0, prop("Tacit Discount %")),
  /* Apply off-peak discount first */
  afterOffPeak, listPrice * (1 - offPeakDiscount),
  /* Apply discretionary discount and round */
  round(afterOffPeak * (1 - discretionaryDiscount), 0)
)

if(
  prop("Financial Route") == "Payment V1",
  if(
    prop("Shadow Validation State") == "Ready",
    round(
      (empty(prop("Shadow Expected Coach Fee (IDR)")) ? 0 : prop("Shadow Expected Coach Fee (IDR)")) +
      (empty(prop("Shadow Expected Coach Fee 2 (IDR)")) ? 0 : prop("Shadow Expected Coach Fee 2 (IDR)"))
    ),
    0
  ),
  if(
    prop("Sale Role") == "Revenue",
    0,
    prop("Events").map(current.prop("Coaches Fee (IDR)")).sum()
  )
)

if(empty(prop("Scheduled")),
  "",
  "⑧ VAT (IDR): " + format(round(prop("VAT (IDR)"), 0))
)

lets(
  /* Get base values with safe defaults */
  listPrice, if(empty(prop("Tacit List Price (IDR)")), 0, prop("Tacit List Price (IDR)")),
  offPeakDiscount, if(empty(prop("Shared Discount %")), 0, prop("Shared Discount %")),
  discretionaryDiscount, if(empty(prop("Tacit Discount %")), 0, prop("Tacit Discount %")),
  /* Apply off-peak discount to get discounted coaching price */
  discountedCoaching, listPrice * (1 - offPeakDiscount),
  /* Calculate final discretionary discount amount and round */
  round(discountedCoaching * discretionaryDiscount, 0)
)

if(empty(prop("Scheduled")),
  "",
  format(year(prop("Scheduled")))
)

if(empty(prop("Scheduled")),
  empty(),
  "⑤ Shared Discount (IDR): " + format(round(prop("Shared Discount (IDR)"), 0))
)

if(empty(prop("Scheduled")),
  "",
  formatDate(prop("Scheduled"), "ddd, YYYY-MM-DD")
)

if(empty(prop("Events")),
  empty(),
  /* Get the Scheduled date from the first related Event */
  prop("Events").first().prop("Scheduled")
)

if(empty(prop("Scheduled")), "",
  "④ Tacit List Price (IDR): " + format(round(prop("Tacit List Price (IDR)"), 0))
)

round(
  /* Use list price or 0 if empty */
  if(empty(prop("Tacit List Price (IDR)")), 0, prop("Tacit List Price (IDR)")) *
  /* Use discount percentage or 0 if empty */
  if(empty(prop("Shared Discount %")), 0, prop("Shared Discount %")),
  0
)

if(empty(prop("Scheduled")),
  empty(),
  style("⑦ Academy Fees (IDR): " + format(round(prop("Academy Fees (IDR)"), 0)), "b")
)

if(empty(prop("Scheduled")),
  empty(),
  style(
    "③ Court Rental (IDR): " + format(round(prop("Court Rental (IDR)"), 0)),
    "b",
    "red"
  )
)

if(prop("Sale Role") != "Wallet" or empty(prop("Wallet Value (IDR)")), empty(),
  prop("Wallet Value (IDR)") + if(empty(prop("Wallet Bonus Credit (IDR)")), 0, prop("Wallet Bonus Credit (IDR)"))
)

if(empty(prop("Scheduled")), empty(),
  lets(
    t, if(empty(prop("Tacit %")), 0, round(prop("Tacit %") * 100)),
    c, if(empty(prop("Club %")), 0, round(prop("Club %") * 100)),
    tp, if(empty(prop("Third Party %")), 0, round(prop("Third Party %") * 100)),
    "⑩ Split: Tacit " + format(t) + "% · Club " + format(c) + "% · Third Party " + format(tp) + "%"
  )
)

lets(
  tacitPct, if(empty(prop("Tacit %")), 0, prop("Tacit %")),
  clubPct, if(empty(prop("Club %")), 0, prop("Club %")),
  thirdPartyPct, if(empty(prop("Third Party %")), 0, prop("Third Party %")),
  total, round((tacitPct + clubPct + thirdPartyPct) * 100, 0),
  if(tacitPct == 0 and clubPct == 0 and thirdPartyPct == 0,
    style("⚠️ Split percentages not set", "b", "red"),
    if(total != 100,
      style("⚠️ Split total = " + format(total) + "% (must be 100%)", "b", "red"),
      ""
    )
  )
)
